				for _, cluster := range []string{\"prod\", \"dr\", \"\"} {
					items = append(items, store.K8sInventoryItem{ClusterID: cluster, Namespace: \"default\", Kind: kind, Name: \"api\", Status: \"Pending\"})
					e := store.K8sEvent{ClusterID: cluster, Namespace: \"default\", InvolvedKind: kind, InvolvedName: \"api\", Reason: \"FailedScheduling\", Message: messages[cluster]}
					if fallback { e.InvolvedKind, e.InvolvedName = \"Pod\", \"api-child\" }
					events = append(events, e)
				}
				seen := map[string]bool{}
				for _, f := range AnalyzeRCA(items, events) {
					if f.Condition "'!= "Pending" { continue }
					key := f.ClusterID+"/"+f.Condition
					if seen[key] { t.Fatalf("duplicate finding: %+v", f) }; seen[key] = true
					want := "FailedScheduling: " + messages[f.ClusterID]
					if len(f.Evidence) != 1 || f.Evidence[0] != want { t.Errorf("%s evidence=%v, want %q", key, f.Evidence, want) }
					if wantCause := pendingCause([]store.K8sEvent{{Message: messages[f.ClusterID]}}); f.Cause != wantCause { t.Errorf("%s cause=%q, want %q", key, f.Cause, wantCause) }
				}
				if len(seen) != 3 { t.Fatalf("expected three Pending findings, got %v", seen) }
			})
		}
	}
}

